# SOLUTION 6
def vending_machine_solution(state, event, data=None):
    match (state, event):
        case ("idle", "coin_inserted"):
            return ("selecting", "Coin accepted. Please select item.")
        case ("selecting", "item_selected"):
            return ("paying", f"Item {data} selected. Insert payment.")
        case ("paying", "payment_complete"):
            return ("dispensing", "Payment received. Dispensing item.")
        case ("dispensing", "item_dispensed"):
            return ("idle", "Item dispensed. Thank you!")
        case _:
            return (state, "Invalid transition")

# SOLUTION 7
def simplify_solution(expr):
    match expr:
        case ["add", 0, x] | ["add", x, 0]:
            return simplify_solution(x)
        case ["mul", 1, x] | ["mul", x, 1]:
            return simplify_solution(x)
        case ["mul", 0, _] | ["mul", _, 0]:
            return 0
        case ["sub", x, 0]:
            return simplify_solution(x)
        case ["add", ["add", a, b], c]:
            return simplify_solution(["add", a, b, c])
        case [op, left, right]:
            return [op, simplify_solution(left), simplify_solution(right)]
        case _:
            return expr
