# SOLUTION 8
def parse_protocol_solution(message):
    parts = message.split()
    match parts:
        case ["GET" | "POST" | "PUT" | "DELETE" as cmd, path, version]:
            return {"protocol": "HTTP", "command": cmd, "args": [path, version]}
        case ["USER", username]:
            return {"protocol": "FTP", "command": "USER", "args": [username]}
        case ["MAIL", "FROM:" as _, email]:
            return {"protocol": "SMTP", "command": "MAIL", "args": [email]}
        case _:
            if ":" in message:
                parts = message.split(":")
                return {"protocol": "Custom", "command": parts[0], "args": parts[1:]}
            return {"protocol": "Unknown", "command": "", "args": []}

