# SOLUTION 10
def type_check_solution(value, type_spec):
    match type_spec:
        case "int":
            return isinstance(value, int) and not isinstance(value, bool)
        case "str":
            return isinstance(value, str)
        case "bool":
            return isinstance(value, bool)
        case ["list", elem_type]:
            return isinstance(value, list) and all(
                type_check_solution(item, elem_type) for item in value
            )
        case ["dict", key_type, val_type]:
            return isinstance(value, dict) and all(
                type_check_solution(k, key_type) and type_check_solution(v, val_type)
                for k, v in value.items()
            )
        case ["optional", inner_type]:
            return value is None or type_check_solution(value, inner_type)
        case ["union", type1, type2]:
            return type_check_solution(value, type1) or type_check_solution(value, type2)
        case _:
            return False

